SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");
load "work/deg10/next_cases_20261030/C242/geometry/deps/native_group_generators.m";
load "work/deg10/next_cases_20261030/C242/geometry/deps/class_group_direct_RR_checked_v4_fastfb.m";
k:=GF(5);A<t>:=FunctionField(k);D:=t^2+13*t+49;N:=t^2+5*t+1;MM:=t^4+14*t^3+63*t^2+70*t-7;aa:=-N/(48*D);bb:=MM/(864*D^2);E:=EllipticCurve([A|0,0,0,aa,bb]);RX<X>:=PolynomialRing(A);p3:=DivisionPolynomial(E,3);p3/:=LeadingCoefficient(p3);assert IsIrreducible(p3);K<x3>:=FunctionField(p3);RY<Y>:=PolynomialRing(K);pY:=Y^2-(x3^3+(K!aa)*x3+K!bb);assert IsIrreducible(pY);L<y3>:=FunctionField(pY);RZ<Z>:=PolynomialRing(L);p2:=Z^3+(L!(K!aa))*Z+L!(K!bb);assert IsIrreducible(p2);W<r2>:=FunctionField(p2);F:=RationalExtensionRepresentation(W);assert Genus(F) eq 9;coords:=[F!(W!(L!(K!t))),F!r2,F!(W!(L!x3)),F!(W!y3)];
jf:=F!(W!(L!(K!jInvariant(E))));cs:=Poles(jf);assert Sort([Degree(p):p in cs]) eq [1:i in [1..8]] cat [2:i in [1..4]];rho:=F!(W!(L!(K!(MM/(12*N*D)))));hh:=coords[4]/(coords[3]-rho);records:=[* *];branches:=AssociativeArray();for b in [0..3] do branches[b]:=[];end for;
for i in [1..#cs] do p:=cs[i];vt:=Valuation(coords[1],p);assert vt ne 0 and Valuation(hh,p) eq 0;vv:=Valuation(coords[2]-rho,p);assert vv ge 0;kind:=vv eq 0 select 0 else 1;h2:=Evaluate(hh^2,p);kp:=Parent(h2);
 if vt gt 0 then if h2 eq kp!(1/84) then branch:=0;else assert h2 eq kp!(-1/28);branch:=1;end if;
 else if h2 eq kp!(1/4) then branch:=2;else assert h2 eq kp!(-1/12);branch:=3;end if;end if;
 Append(~branches[branch],i);Append(~records,[*i,Degree(p),vt,vv,branch,kind,[Integers()!x:x in Eltseq(h2,k)]*]);end for;
assert #branches[0] eq 4 and #branches[1] eq 2 and #branches[2] eq 4 and #branches[3] eq 2;
base:=Divisor(cs[branches[2][1]]);ivs:=ClassGroupAbelianInvariants(F:ReductionDivisor:=base,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G:=F`cld`Cl;print "C242_V9_GROUP_PROVEN",Invariants(G),Cputime(tt);
GG,_,phi,witness:=MDClassGroupDirectRRCheckedV4FastFB(F,"work/deg10/next_cases_20261030/C242/geometry/forgetful9_setup_RR.log");assert GG cmpeq G;cc:=[phi(Divisor(p)-Degree(p)*base):p in cs];hg:=[cc[i]:i in branches[2] cat branches[3]] cat [3*cc[i]:i in branches[1]];orbitweights:=[*[*[i],1*]:i in branches[2] cat branches[3]*] cat [*[*[i],3*]:i in branches[1]*];
for kind in [0,1] do inds:=[i:i in branches[0]|records[i][6] eq kind];assert #inds eq 2 and &and[Degree(cs[i]) eq 1:i in inds];Append(~hg,3*&+[cc[i]:i in inds]);Append(~orbitweights,[*inds,3*]);end for;
H:=sub<G|hg>;assert (182*1092*131040) mod #H eq 0;QH,qh:=quo<G|H>;comps:=[*{QH!0}*] cat [*{QH|}:i in [1..6]*];for i in [1..#cs] do w:=Degree(cs[i]);for d in [w..6] do comps[d+1] join:={z+qh(cc[i]):z in comps[d-w+1]};end for;end for;
function ER(v) return [[Integers()!x:x in Coefficients(Numerator(v))],[Integers()!x:x in Coefficients(Denominator(v))]];end function;
function EF(v) return [ER(x):x in Eltseq(F!v)];end function;
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);function EP(pl) I:=Ideal(pl);return [*Order(I) eq OF select 1 else 0,Degree(pl),[EF(v):v in Basis(I)]*];end function;
ff:=F`cld`ZnToCl;Zn:=Domain(ff);fb:=Reverse([x`place:x in F`cld`fb]);fc:=[ff(Zn.i):i in [1..#fb]];pa,ma:=Support(F`cld`A1);assert #pa eq 1 and ma[1] eq 1;ai:=Index(fb,pa[1]);assert ai gt 0;
out:=[*[ER(v):v in Coefficients(DefiningPolynomial(F))],[Order(Ideal(p)) eq OF select 1 else 0:p in fb],[Degree(p):p in fb],[*[EF(v):v in Basis(Ideal(p))]:p in fb*],[Eltseq(v):v in fc],[Eltseq(v):v in Rows(RelationMatrix(G))],[EF(v):v in coords],ai,[Degree(p):p in cs],[Eltseq(v):v in cc],[EP(p):p in cs],EP(Support(base)[1]),[Eltseq(v):v in hg],[[Eltseq(v):v in co]:co in comps],orbitweights,records*];Write("work/deg10/next_cases_20261030/C242/geometry/forgetful9_proven_picard.m",Sprint(out):Overwrite:=true);fprintf witness,"]\n";Flush(witness);printf "C242_FORGETFUL9_PROVEN_COMPLETE G=%o H=%o index=%o comps=%o FB=%o cpu=%o\n",Invariants(G),Invariants(H),#TorsionSubgroup(QH),[#c:c in comps],#fb,Cputime(tt);quit;
